    internal static OptionDictionary<T> ReadDictionary<T>(JsonElement json, Func<JsonElement, T> read)
    {
        if (json.ValueKind != JsonValueKind.Object) throw new JsonException("Expected dictionary object.");
        var result = new OptionDictionary<T>();
        foreach (var property in json.EnumerateObject())
        {
            try { result.Add(property.Name, read(property.Value)); }
            catch (Exception error) when (OptionReadError.Is(error)) { throw OptionReadError.AtProperty(property.Name, error); }
        }
        return result;
    }

    internal static T[] ReadArray<T>(JsonElement json, Func<JsonElement, T> read)
    {
        if (json.ValueKind != JsonValueKind.Array) throw new JsonException("Expected array.");
        var values = new T[json.GetArrayLength()];
        var i = 0;
        foreach (var item in json.EnumerateArray())
        {
            try { values[i] = read(item); }
            catch (Exception error) when (OptionReadError.Is(error)) { throw OptionReadError.AtIndex(i, error); }
            i++;
        }
        return values;
    }

    // The visualMap subtype defaulter of ECharts 6.1.0 (component/visualMap/installCommon.js).
    internal static bool ContinuousVisualMapDefault(JsonElement json)
    {
        static bool Has(JsonElement json, string name, out JsonElement value) => json.TryGetProperty(name, out value) && value.ValueKind != JsonValueKind.Null;
        var split = Has(json, "pieces", out var pieces) ? pieces.ValueKind == JsonValueKind.Array && pieces.GetArrayLength() > 0 : Has(json, "splitNumber", out var number) && number.ValueKind == JsonValueKind.Number && number.GetDouble() > 0;
        return !Has(json, "categories", out _) && (!split || Has(json, "calculable", out var calculable) && calculable.ValueKind == JsonValueKind.True);
    }

    internal static bool IsInstant(JsonElement json)
    {
        if (json.ValueKind != JsonValueKind.String || !json.TryGetDateTimeOffset(out _)) return false;
        var text = json.GetString()!;
        var time = text.IndexOfAny(['T', 't', ' ']);
        return time > 0 && (text.EndsWith('Z') || text.EndsWith('z') || text.AsSpan(time).IndexOfAny('+', '-') > 0);
    }

    internal static OneOrMany<T> ReadOneOrMany<T>(JsonElement json, Func<JsonElement, T> read, Func<JsonElement, bool> one) =>
        json.ValueKind == JsonValueKind.Array && !one(json) ? OneOrMany<T>.Many(ReadArray(json, read)) : OneOrMany<T>.One(read(json));
